/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X audio engine: the five parts, the mixer, the send FX and the master, driven by
 * the sequencer. engine_render() runs in the audio ISR; everything else is called
 * from the main loop and reaches the ISR through the command queue. A project
 * replacement first holds the ISR, then rebuilds the engines from the main loop.
 *
 * Parameters are addressed as (target, voice, index) -> pot value, the same triple
 * the UI pages, the project file and the command queue use:
 *   T_909 / T_808   voice = track 0..10, or DR_KIT / D8_KIT (= 11) for the kit
 *   T_303           voice = 0 / 1 (303 A / B)
 *   T_BRK           voice 0: breaks.h params (the per-pattern ones live in the pattern)
 *   T_FX            voice 0: fxbus.h params (reverb, delay, master drive / comp)
 *   T_MIX           voice = part 0..4: Level, Rev send, Dly send, Pan, channel cutoff
 *                   (drums: sends on top of the per-voice sends; cutoff is on the bus,
 *                   before the master filter)
 *   T_MST           voice 0: master filter + limiter
 */
#pragma once
#include <stdint.h>
#include "../dsp/x0x_param.h"
#include "../seq/sequencer.h"
#include "../seq/motion.h"

enum { T_909, T_808, T_303, T_BRK, T_FX, T_MIX, T_MST, NTARGETS };
#define T_PROB NTARGETS                /* a lane's pseudo-target: a step's chance, 5..100 % (not in sound_t);
                                        * voice = part << 4 | drum track (0 on the 303s and the break) */
#define T_VEL (T_PROB + 1)             /* drum step velocity 1..127 (not in sound_t); same voice packing as T_PROB.
                                        * MOT_NONE / base 0 = legacy accent / accent_q7 law. 303s keep bstep.velocity. */
enum { PART_909, PART_808, PART_303A, PART_303B, PART_BRK, NPARTS };
/* T_MIX, per part: level, reverb send, delay send, pan (64 = centre),
 * channel cutoff (127 = open, before the master filter). */
enum { MX_LEVEL, MX_REV, MX_DLY, MX_PAN, MX_CUT, MX_NPARAMS };
#define NVOICES_MAX 12                 /* a drum machine: 11 tracks + the kit */
#define NPARAMS_MAX 32                 /* params per (target, voice); fills at Chicago aux PBend/Damp 30..31 */

/* Review-only runtime and separately guarded tagged-storage units; defaults OFF. */
#ifndef X0X_BASS_PRESET_PREVIEW
#define X0X_BASS_PRESET_PREVIEW 0
#endif
#ifndef X0X_BASS_TAGGED_SOUND
#define X0X_BASS_TAGGED_SOUND 0
#endif
#ifndef X0X_BASS_NOTE_SOUND
#define X0X_BASS_NOTE_SOUND 0
#endif
#if X0X_BASS_NOTE_SOUND && !X0X_BASS_TAGGED_SOUND
#error Note sounds require tagged bass storage
#endif
#if X0X_BASS_TAGGED_SOUND && !X0X_BASS_PRESET_PREVIEW
#error Tagged bass unit requires the reviewed runtime preset unit
#endif
#if X0X_BASS_TAGGED_SOUND
#include "bass_identity.h"
#endif
#if X0X_BASS_PRESET_PREVIEW
#include "factory_banks.h"
const x0x_param_t *engine_bass_bank_param(int bank, int param);
int engine_bass_bank(int voice);
int engine_bass_bank_available(int voice, int bank);
int engine_bass_preset_index(int voice);
int engine_bass_preset_edited(int voice);
int engine_bass_requested_bank(int voice);
int engine_bass_requested_preset(int voice);
/* 0 applied; 1 next audio boundary; 2 held/release tail; 3 wheel; 4 sound locks; 5 old input; 6 publication. */
int engine_bass_preset_pending(int voice);
void engine_bass_cancel_preset(int voice);
/* Main-loop edit/undo snapshots defer preset application without muting audio. */
void engine_bass_edit_hold(int hold);
int engine_bass_preview_changed(void);
void engine_bass_wheel_owners(uint8_t mask);
#endif

/* the sound of a project: every pot of every engine, mirrored here by the main loop */
typedef struct {
    uint8_t v[NTARGETS][NVOICES_MAX][NPARAMS_MAX];
#if X0X_BASS_TAGGED_SOUND
    bass_sound_tag_t bass[NBASS]; /* explicit LE bytes; never native ABI encoding */
#endif
} sound_t;
#if X0X_BASS_TAGGED_SOUND
int engine_bass_sound_bank(const sound_t *sound,int voice);
/* Compact undo candidate: no project-sized automatic scratch. */
typedef struct { uint8_t cell[NBASS][NPARAMS_MAX]; bass_sound_tag_t tag[NBASS]; } bass_base_state_t;
int engine_bass_base_ready(unsigned mask,const bass_base_state_t *target);
void engine_bass_base_restore(unsigned mask); /* caller holds audio; ready was 0 */
uint32_t engine_bass_choice_serial(void);

int engine_bass_sound_validate(const sound_t *sound);
int engine_bass_sound_adopt(sound_t *sound,int bank0,int bank1);
void engine_bass_sound_refresh(sound_t *sound,int voice);
#if X0X_BASS_NOTE_SOUND
#include "bass_note_sound.h"
int engine_bass_note_validate(const lane_t *lane);
int engine_bass_note_capture(lane_t *lanes,int pat,int voice,int step,const sound_t *sound);
#endif
#endif
#if X0X_BASS_PRESET_PREVIEW
int engine_bass_select_preset(int voice, int bank, int preset, sound_t *sound);
#endif

extern seq_t seq;                      /* the sequencer (its pattern pointer is the project's) */
/* render stages (the PERF screen): 909, 808, 303 A, 303 B, BREAK, FX, MASTER, SEQ */
enum { PR_909, PR_808, PR_303A, PR_303B, PR_BRK, PR_FX, PR_MST, PR_SEQ, ENG_PROF_N };
extern volatile uint32_t eng_prof[ENG_PROF_N], eng_prof_frames;
void engine_motion_enable(int on);                          /* off: lanes do not play (the PERF test) */
void engine_smc_solo(uint8_t mask);                         /* runtime SMC solo mask; 0 = all parts audible */
void engine_smc_solo_targets(uint8_t parts, uint16_t kit909, uint16_t kit808); /* union of parts and drum tracks */
void engine_fx_mute(uint8_t mask);                          /* runtime output gates, never edits intended pots or motion */
uint8_t engine_fx_muted(void);
void engine_smc_busfx(uint8_t down, const uint8_t effect[8]); /* SMC momentary buses; effect may be null */
void engine_motion_reset(void);                             /* lanes replaced (undo): knobs to their own values */
/* overload guard (engine.c): the platform reports each block's load after rendering it */
void engine_load(uint32_t pct, uint32_t frames);           /* ISR, after engine_render */
void engine_guard_enable(int on);                           /* off: full quality always (the PERF test) */
int engine_guard_active(void);
extern volatile uint32_t eng_guard_count;                   /* times it engaged (PERF screen) */
extern volatile uint8_t eng_step[NTRACKS];   /* playheads for the UI */
extern volatile uint16_t eng_peak[NPARTS];   /* part meters, Q15, decaying (UI) */
extern volatile uint8_t eng_hit[NKIT][NDRUM]; /* each drum track's last hit, 255 = full velocity (the UI lets it fall) */
#define SCOPE_N 128u                   /* power-of-two ring; 128 frees 256 B pool vs 256 */
extern int16_t eng_scope[SCOPE_N];     /* the last output samples, for the screen */
extern volatile uint32_t eng_scope_w;

void engine_init(pattern_t *patterns, song_t *song, lane_t *lanes, const sound_t *base);
void engine_render(int32_t *out_lr, uint32_t n);   /* ISR: n stereo frames, 24-bit in int32 */
/* Main loop project transaction. The render and main loop run on the same core; once held,
 * the ISR emits silence without reading project or sample memory.
 * Flush on the old channels before replacing the project, then engine_init + apply its sound.
 * Releasing an aborted transaction preserves the sequencer and queued parameter commands. */
void engine_project_hold(int hold);
void engine_project_release(void);              /* end a transaction; discard MIDI received while held */
int engine_project_notes(void);                 /* held or queued notes: cannot begin a transfer */
void engine_project_flush(void);                /* held only: end old output notes and transport */

/* parameter descriptors (UI) */
int engine_nvoices(int target);
int engine_nparams(int target, int voice);
const x0x_param_t *engine_param(int target, int voice, int i);
const char *engine_voice_name(int target, int voice);
#if X0X_DEV_WOBBLE
int engine_bass_is_wobble(int voice); /* live WBL1 backend on 303 A/B voice */
#else
static inline int engine_bass_is_wobble(int voice)
{
    (void)voice;
    return 0;
}
#endif

/* main loop -> ISR */
void engine_set(int target, int voice, int i, int value);   /* queued; the sound_t mirror is the caller's */
void engine_out_loud(int on);          /* 1: the output at the codec's full scale (6 dB hotter than Felucca's) */
void engine_usb_full(int on);          /* 1: engine_render at full level, engine_volume the MASTER knob after */
void engine_volume(int32_t *out_lr, uint32_t n);   /* ISR, after engine_render (and the USB tap) */
void engine_apply_sound(const sound_t *s);                  /* queue every value (load, init) */
void engine_sound_defaults(sound_t *s);                     /* each engine's power-on values */
void engine_sound_centre_drum_pans(sound_t *s);             /* every drum voice's PAN (its last pot) to centre */
void engine_drum(int kit, int voice, float vel);            /* play now (keys) */
void engine_bass_on(int part, int note, int accent, int slide);
void engine_bass_on_velocity(int part, int note, int accent, int slide, int velocity);
void engine_bass_record(int part, int note, int velocity, int flags); /* accepted live REC press, audio-owned */
void engine_bass_off(int part);
void engine_bass_off_note(int part, int note); /* Chicago arp: release one held pitch; 0 note = all */
void engine_brk_live(int key, int down);
void engine_brk_edit_hold(int held);
uint32_t engine_brk_held(void); /* aggregate slice ownership, macros excluded */
int engine_brk_count(int bank); /* currently applied snapshot count; requested changes may wait for release */
void engine_brk_loops(void);                                /* (re)read the A / B loops of the current pattern */
void engine_brk_flush(void);                                /* publish a loop change that waited for the sounding voice */
void engine_brk_drop_range(const uint8_t *base, uint32_t nbytes);
int engine_brk_slice(void);                                 /* slice sounding now, -1 none (UI) */
void engine_brk_state(int *slice, int *bank, int *div, int *running);
int engine_brk_outline(int which, uint8_t *peaks, int n);   /* the loop's peaks for the screen (main loop) */
/* motion (seq/motion.h): lanes play into the engine, never into the sound_t mirror */
int engine_motion_part(int target, int voice);              /* the part a parameter's lane follows */
int engine_motion_value(int lane);                          /* what the lane plays now, -1 none */
void engine_motion_rec(int lane);                           /* record a pass from the next step */
void engine_motion_hold(int lane);                          /* the knob wins for a pass */
void engine_motion_clear(int lane);                         /* free a motion lane (undo / bulk edit) */
float engine_gr_db(void);                                   /* master compressor gain reduction (UI meter) */
int engine_master_get(int i);                             /* read-only applied master pot */
void engine_master_format(int i, char *buf);                /* a master pot in its unit */
int engine_brk_nslots(void);                                /* built-in loops + user slots */
const char *const *engine_brk_slot_names(void);

/* Physical recording edges use the existing audio command queue. */

/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
 * X0X: object map changed (see below). */
/* Persistent storage on the SPI NOR.
 *
 * Every object has an A/B sector pair. A save goes to the copy that is not
 * the current one: erase the sector, program the payload (from offset 256),
 * then the 32-byte header at offset 0 last. The header is the commit record;
 * on load the valid copy with the highest seq wins, so a torn write leaves
 * the previous copy in charge.
 *
 * Flash access goes through three hooks (also used by the host test):
 *   st_read(off, dst, n)   st_erase(off)   st_prog(off, src, n)
 */
#ifndef ST_MAINTENANCE_ADMIT
#define ST_MAINTENANCE_ADMIT() 1
#endif

#define ST_MAGIC 0x30583058u                   /* "X0X0": never mistaken for a Felucca object */
#define ST_SECTOR 4096u
#define ST_PAYLOAD_OFF 256u
#define ST_PAYLOAD_MAX (ST_SECTOR - ST_PAYLOAD_OFF)

/* flash map, X0X (plat.h OBJ_*): settings 0xFC000 (FL_GLOB); sound, patterns 1-8, patterns 9-16,
 * the song at 0x97000.. (2 sectors each, below the user sample slots at 0xA0000); the panel
 * calibration at 0xDC000 and motion at 0xDE000 (Felucca's user-preset area, unused by X0X). Nothing
 * above 0xDFFFF: 0xE0000.. is the update loader's staging area. */
typedef struct {
    uint32_t magic;
    uint16_t type, slot;
    uint32_t seq, len, crc, rsv[2];
    uint32_t hcrc;
} st_hdr_t;

static int st_read(uint32_t off, void *dst, uint32_t n);
static int st_erase(uint32_t off);
static int st_prog(uint32_t off, const void *src, uint32_t n);

#include "crc32_nibble.h"              /* nibble table + x0x_crc32 shared with project/slots/boot */
#define st_crc32 x0x_crc32             /* zlib CRC-32, 4 bits per step */

#if BOARD_SMK37
/* SMK-37 Pro: every object in FL_DATA 0x9D000..0xAFFFF (the stock VM), A/B
 * neighbours in plat.h order: settings 0x9D000, sound 0x9F000, patterns 1-8 0xA1000, patterns 9-16 0xA3000,
 * panel 0xA5000, song 0xA7000, motion 0xA9000 (..0xAAFFF); boot screen A/B at 0xAB000 and
 * 0xAC000 (app/boot_screen.h). A foreign-store clear erases those two with the
 * rest of the store. 0xAD000..0xAEFFF stays spare. The owner tag is at
 * 0xAF000 (st_owner_check). 0xB0000..0xBAFFF is not a sample slot and not the store: the
 * owner check never clears it. Never near BTIF / USRTRIM (0xC0000..0xC1FFF) or key_mac (0xFF000). */
#define ST_SMK_BASE 0x9D000u
_Static_assert(ST_SMK_BASE + 2u * OBJ_NOBJ * ST_SECTOR <= 0xAF000u, "SMK store: objects past the owner tag");
_Static_assert(ST_SMK_BASE + 2u * OBJ_NOBJ * ST_SECTOR == 0xAB000u, "boot screen sectors must follow the objects");
static uint32_t st_sector(uint32_t obj, uint32_t copy)  /* flash offset of copy A (0) / B (1) */
{
    return ST_SMK_BASE + ((obj % OBJ_NOBJ) * 2u + (copy & 1u)) * ST_SECTOR;
}

/* The owner of the store. Several FM-1 firmwares are ported to the SMK-37 Pro with the same board layer and
 * this same store area, each with its own object formats: a firmware must never parse another's data. The
 * sector 0xAF000 holds "SMK37DATA" + the firmware family (FELUCCA_DATA_FAMILY, build.py: X0X). Ours: load as
 * ever. None (erased): data of unknown origin, kept only if FELUCCA_DATA_UNTAGGED_OK (X0X: 0, cleared).
 * Another family's: clear the whole store area below the tag (0x9D000..0xAEFFF, the other firmware's objects
 * included) and take it. Samples (FL_SMP) validate themselves. Calibration, BT pairing and key_mac are outside
 * FL_DATA: never touched. Called once at boot, before the first store read (app/main_fm1.c). */
#ifndef FELUCCA_DATA_FAMILY
#define FELUCCA_DATA_FAMILY "X0X"
#endif
#ifndef FELUCCA_DATA_UNTAGGED_OK
#define FELUCCA_DATA_UNTAGGED_OK 0
#endif
#define ST_OWNER_SECTOR 0xAF000u
#ifndef ST_IDLE
#define ST_IDLE() ((void)0)                     /* (x0x.c: feed the watchdog between erases) */
#endif
_Static_assert(ST_OWNER_SECTOR + ST_SECTOR <= 0xB0000u, "SMK store owner: past FL_DATA (the VM spare follows)");
static uint8_t st_owner_cleared;                /* (the UI says so at boot) */
static void st_owner_check(void)
{
    static const char FAM[] = FELUCCA_DATA_FAMILY;
    uint8_t tag[16], want[16];
    uint32_t i, erased = 1, ours = 1, s;
    for (i = 0; i < 16u; i++)
        want[i] = i < 9u ? (uint8_t)"SMK37DATA"[i] : i - 9u < sizeof FAM - 1u ? (uint8_t)FAM[i - 9u] : 0u;
    if (st_read(ST_OWNER_SECTOR, tag, 16))
        return;
    for (i = 0; i < 16u; i++) {
        erased &= tag[i] == 0xFFu;
        ours &= tag[i] == want[i];
    }
    if (ours)
        return;
    if (!erased || !FELUCCA_DATA_UNTAGGED_OK) {     /* another firmware's store (or unknown): clear it */
        for (s = ST_SMK_BASE; s < ST_OWNER_SECTOR; s += ST_SECTOR) {
            st_erase(s);
            ST_IDLE();
        }
        st_owner_cleared = 1;
    }
    st_erase(ST_OWNER_SECTOR);
    st_prog(ST_OWNER_SECTOR, want, 16);
}
#else
static uint32_t st_sector(uint32_t obj, uint32_t copy)  /* flash offset of copy A (0) / B (1) */
{
    if (obj == OBJ_SET)
        return 0xFC000u + copy * ST_SECTOR;
    if (obj == OBJ_PANEL)
        return 0xDC000u + copy * ST_SECTOR;
    if (obj == OBJ_MOTION)
        return 0xDE000u + copy * ST_SECTOR;
    if (obj == OBJ_SONG)
        return 0x9D000u + copy * ST_SECTOR;
    return 0x97000u + (obj - OBJ_SOUND) * 2u * ST_SECTOR + copy * ST_SECTOR;   /* SOUND, PAT0, PAT1 */
}
#endif

static uint8_t st_buf[ST_PAYLOAD_MAX] __attribute__((aligned(4)));
static uint8_t st_stage_hold;             /* boot screen is filling st_buf; saves must not clobber it */

/* The boot screen stages its record in this existing buffer. A second buffer
 * would not fit. While held, load and save fail and leave the bytes alone. */
uint8_t *store_stage_lock(uint32_t *cap)
{
    if (!ST_MAINTENANCE_ADMIT())
        return 0;
    if (st_stage_hold)
        return 0;
    st_stage_hold = 1;
    if (cap)
        *cap = (uint32_t)sizeof st_buf;
    return st_buf;
}
void store_stage_unlock(void) { st_stage_hold = 0; }
int store_stage_held(void) { return st_stage_hold; }

static int st_head(uint32_t obj, uint32_t copy, st_hdr_t *h)   /* commit record valid: 0 */
{
    if (st_read(st_sector(obj, copy), h, sizeof *h))
        return -1;
    if (h->magic != ST_MAGIC || h->type != obj || h->len > ST_PAYLOAD_MAX ||
        h->hcrc != st_crc32(h, sizeof *h - 4u))
        return -1;
    return 0;
}

static int st_body(uint32_t obj, uint32_t copy, const st_hdr_t *h)   /* payload -> st_buf, CRC ok: 0 */
{
    if (st_read(st_sector(obj, copy) + ST_PAYLOAD_OFF, st_buf, h->len) || st_crc32(st_buf, h->len) != h->crc)
        return -1;
    return 0;
}

/* the current copy: the valid one with the highest seq (A on a tie), -1 when
 * neither is valid. Headers first, so only the winner's payload is read (it
 * is left in st_buf); *h gets its header. */
static int st_current(uint32_t obj, st_hdr_t *h)
{
    st_hdr_t a, b;
    int va = st_head(obj, 0, &a) == 0, vb = st_head(obj, 1, &b) == 0;
    if (vb && (!va || b.seq > a.seq)) {
        if (st_body(obj, 1, &b) == 0) {
            *h = b;
            return 1;
        }
        vb = 0;
    }
    if (va && st_body(obj, 0, &a) == 0) {
        *h = a;
        return 0;
    }
    if (vb && st_body(obj, 1, &b) == 0) {
        *h = b;
        return 1;
    }
    return -1;
}

/* Body CRC of one copy, through a stack window. Does not write st_buf: the
 * project object buffer is that same array, and it already holds the bytes
 * about to be saved. */
static int st_body_ok(uint32_t obj, uint32_t copy, const st_hdr_t *h)
{
    uint8_t tmp[256];
    uint32_t off = 0, c = 0xFFFFFFFFu;
    while (off < h->len) {
        uint32_t n = h->len - off;
        if (n > sizeof tmp)
            n = (uint32_t)sizeof tmp;
        if (st_read(st_sector(obj, copy) + ST_PAYLOAD_OFF + off, tmp, n))
            return 0;
        c = x0x_crc32_upd(c, tmp, n);
        off += n;
    }
    return (~c) == h->crc;
}

/* The current copy (0 or 1), or -1. Same rule as st_current: the valid body
 * with the highest seq, copy A on a tie. *seq is that copy's seq. */
static int st_pick(uint32_t obj, uint32_t *seq)
{
    st_hdr_t a, b;
    int va = st_head(obj, 0, &a) == 0, vb = st_head(obj, 1, &b) == 0;
    if (vb && (!va || b.seq > a.seq)) {
        if (st_body_ok(obj, 1, &b)) {
            *seq = b.seq;
            return 1;
        }
        vb = 0;
    }
    if (va && st_body_ok(obj, 0, &a)) {
        *seq = a.seq;
        return 0;
    }
    if (vb && st_body_ok(obj, 1, &b)) {
        *seq = b.seq;
        return 1;
    }
    return -1;
}

/* load object into dst (up to max bytes); returns the length, or -1 */
static int st_load(uint32_t obj, void *dst, uint32_t max)
{
    st_hdr_t h;
    if (!ST_MAINTENANCE_ADMIT())
        return -1;
    if (st_stage_hold)                            /* do not wipe a boot record being built */
        return -1;
    if (st_current(obj, &h) < 0)
        return -1;
    if (h.len > max)
        h.len = max;
    __builtin_memcpy(dst, st_buf, h.len);
    return (int)h.len;
}

static int st_save(uint32_t obj, const void *src, uint32_t len)
{
    uint32_t seq = 0, base, off;
    int cur, rc;
    st_hdr_t h;
    if (!ST_MAINTENANCE_ADMIT())
        return -8;
    if (st_stage_hold)                            /* refuse; the previous object stays on flash */
        return -8;
    if (len > ST_PAYLOAD_MAX)
        return -1;
    cur = st_pick(obj, &seq);                         /* leaves st_buf alone */
    if (cur < 0)
        seq = 0;
    base = st_sector(obj, cur == 0 ? 1u : 0u);       /* write the other copy */
    if ((const void *)src != (const void *)st_buf)
        __builtin_memcpy(st_buf, src, len);               /* the driver wants RAM sources */
    if ((rc = st_erase(base)) != 0)
        return rc;
    for (off = 0; off < len; off += 256u) {
        uint32_t n = len - off > 256u ? 256u : len - off;
        if ((rc = st_prog(base + ST_PAYLOAD_OFF + off, st_buf + off, n)) != 0)
            return rc;
    }
    h.magic = ST_MAGIC;
    h.type = (uint16_t)obj;
    h.slot = (uint16_t)(cur == 0 ? 1 : 0);
    h.seq = seq + 1u;
    h.len = len;
    h.crc = st_crc32(st_buf, len);
    h.rsv[0] = h.rsv[1] = 0xFFFFFFFFu;
    h.hcrc = st_crc32(&h, sizeof h - 4u);
    if ((rc = st_prog(base, &h, sizeof h)) != 0)       /* the commit record, last */
        return rc;
    {   /* read back: a write-protected or failing part must not report SAVED */
        st_hdr_t chk;
        uint32_t c = cur == 0 ? 1u : 0u;
        if (st_head(obj, c, &chk) || chk.seq != h.seq || st_body(obj, c, &chk))
            return -7;
    }
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* LCD wiring, SPI1. The panel protocol is src/lcd.c.
 *
 * FM-1:       SPI1 group B (IOMAP_CON1 bit4 = 1): PC9 CLK, PC10 DO; PC7 CS, PC8 D/C;
 *             backlight PA2, active low.
 * SMK-37 Pro: SPI1 group A (IOMAP_CON1 bit4 = 0): PB6 CLK, PB7 DO; PC8 CS, PB5 D/C;
 *             no backlight control (always on). Group B (PC10) carries the 16 RGB pad
 *             LEDs (WS2812 class) instead: fm1_padled_send() switches SPI1 over for one
 *             frame while the LCD CS is high, as the stock firmware does (stock v016;
 *             AC79 SDK spi.h for the pin groups).
 *
 *   fm1_lcd_hw_init()          pins, backlight on, SPI1 master at BAUD 4
 *   fm1_lcd_baud(b)            SPI1 clock = lsb / (b + 1)
 *   fm1_lcd_send_cmd(c)        D/C low, CS low, one byte (then fm1_lcd_wait)
 *   fm1_lcd_send_data(p, n)    D/C high, CS low, DMA n bytes from RAM p
 *   fm1_lcd_wait()             SPI done (or timeout, counted), pending cleared
 *   fm1_lcd_deselect()         CS high
 * SMK-37 Pro only:
 *   fm1_padled_send(p, n)      LCD deselected and idle: SPI1 to PC10 at BAUD 8, DMA n bytes
 *                              (then fm1_lcd_wait, then fm1_padled_done)
 *   fm1_padled_done()          SPI1 back to the LCD pins at the LCD baud
 */
#pragma once
#include <stdint.h>
#include "fm1_cc.h"

#define FM1_LCD_PA_OUT (*(volatile uint32_t *)0x50000u)
#define FM1_LCD_PA_DIR (*(volatile uint32_t *)0x50008u)
#define FM1_LCD_PB_OUT (*(volatile uint32_t *)0x50040u)
#define FM1_LCD_PB_DIR (*(volatile uint32_t *)0x50048u)
#define FM1_LCD_PC_OUT (*(volatile uint32_t *)0x50080u)
#define FM1_LCD_PC_DIR (*(volatile uint32_t *)0x50088u)
#define FM1_LCD_IOMAP_CON1 (*(volatile uint32_t *)0x51020u)
#define FM1_LCD_SPI_CON (*(volatile uint32_t *)0x11D00u)
#define FM1_LCD_SPI_BAUD (*(volatile uint32_t *)0x11D04u)
#define FM1_LCD_SPI_BUF (*(volatile uint32_t *)0x11D08u)
#define FM1_LCD_SPI_ADR (*(volatile uint32_t *)0x11D0Cu)
#define FM1_LCD_SPI_CNT (*(volatile uint32_t *)0x11D10u)
#define FM1_LCD_GROUP_B 0x10u             /* IOMAP_CON1 bit4: SPI1 on PC8/PC9/PC10 */

#if BOARD_SMK37
#define FM1_LCD_CS_OUT FM1_LCD_PC_OUT
#define FM1_LCD_CS (1u << 8)              /* PC8 */
#define FM1_LCD_DC_OUT FM1_LCD_PB_OUT
#define FM1_LCD_DC (1u << 5)              /* PB5 */
#define FM1_LCD_CLK (1u << 6)             /* PB6 */
#define FM1_LCD_DO (1u << 7)              /* PB7 */
#define FM1_PADLED_DO (1u << 10)          /* PC10 */
#define FM1_PADLED_BAUD 8u                /* lsb / 9 = 6.67 MHz: one SPI byte per LED bit */
#else
#define FM1_LCD_CS_OUT FM1_LCD_PC_OUT
#define FM1_LCD_CS (1u << 7)              /* PC7 */
#define FM1_LCD_DC_OUT FM1_LCD_PC_OUT
#define FM1_LCD_DC (1u << 8)              /* PC8 */
#define FM1_LCD_CLK (1u << 9)             /* PC9 */
#define FM1_LCD_DO (1u << 10)             /* PC10 */
#define FM1_LCD_BL (1u << 2)              /* PA2, active low */
#endif

static uint32_t fm1_lcd_timeouts;
static uint8_t fm1_lcd_cur_baud = 4u;

FM1_INLINE void fm1_lcd_hw_init(void)
{
#if BOARD_SMK37
    FM1_LCD_IOMAP_CON1 &= ~FM1_LCD_GROUP_B;
    FM1_LCD_CS_OUT |= FM1_LCD_CS;
    FM1_LCD_PC_DIR &= ~FM1_LCD_CS;
    FM1_LCD_PB_OUT &= ~(FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
    FM1_LCD_PB_DIR &= ~(FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
    FM1_LCD_PC_OUT &= ~FM1_PADLED_DO;     /* the LED line idles low (latch) */
    FM1_LCD_PC_DIR &= ~FM1_PADLED_DO;
#else
    FM1_LCD_PA_OUT &= ~FM1_LCD_BL;
    FM1_LCD_PA_DIR &= ~FM1_LCD_BL;
    FM1_LCD_IOMAP_CON1 |= FM1_LCD_GROUP_B;
    FM1_LCD_CS_OUT |= FM1_LCD_CS;
    FM1_LCD_PC_OUT &= ~(FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
    FM1_LCD_PC_DIR &= ~(FM1_LCD_CS | FM1_LCD_DC | FM1_LCD_CLK | FM1_LCD_DO);
#endif
    FM1_LCD_SPI_CON = 0x4021u;
    FM1_LCD_SPI_BAUD = 4u;
    fm1_lcd_cur_baud = 4u;
}

FM1_INLINE void fm1_lcd_baud(uint32_t b)
{
    FM1_LCD_SPI_BAUD = b;
    fm1_lcd_cur_baud = (uint8_t)b;
}

static void fm1_lcd_wait(void)
{
    uint32_t n;
    for (n = 0; n < 4000000u && !(FM1_LCD_SPI_CON & 0x8000u); n++)
        ;
    if (n == 4000000u)
        fm1_lcd_timeouts++;
    FM1_LCD_SPI_CON |= 0x4000u;
}

FM1_INLINE void fm1_lcd_deselect(void) { FM1_LCD_CS_OUT |= FM1_LCD_CS; }

FM1_INLINE void fm1_lcd_send_cmd(uint8_t c)
{
    FM1_LCD_DC_OUT &= ~FM1_LCD_DC;
    FM1_LCD_CS_OUT &= ~FM1_LCD_CS;
    FM1_LCD_SPI_CON |= 0x4000u;
    FM1_LCD_SPI_BUF = c;
}

FM1_INLINE void fm1_lcd_send_data(const void *p, uint32_t n)
{
    FM1_LCD_DC_OUT |= FM1_LCD_DC;
    FM1_LCD_CS_OUT &= ~FM1_LCD_CS;
    FM1_LCD_SPI_CON |= 0x4000u;
    FM1_LCD_SPI_ADR = (uint32_t)(uintptr_t)p;
    FM1_LCD_SPI_CNT = n;
}

#if BOARD_SMK37
FM1_INLINE void fm1_padled_send(const void *p, uint32_t n)
{
    FM1_LCD_CS_OUT |= FM1_LCD_CS;         /* the panel ignores the bus */
    FM1_LCD_SPI_BAUD = FM1_PADLED_BAUD;
    FM1_LCD_IOMAP_CON1 |= FM1_LCD_GROUP_B;
    FM1_LCD_SPI_CON |= 0x4000u;
    FM1_LCD_SPI_ADR = (uint32_t)(uintptr_t)p;
    FM1_LCD_SPI_CNT = n;
}

FM1_INLINE void fm1_padled_done(void)
{
    FM1_LCD_IOMAP_CON1 &= ~FM1_LCD_GROUP_B;
    FM1_LCD_SPI_BAUD = fm1_lcd_cur_baud;
}
#endif

/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 SARADC: PB6 = MASTER pot (ch4),
 * PB1 = battery divider (ch3). Polled, 10 bit, from the main loop.
 *
 *   fm1_adc_init()        both pins analog inputs, no pulls
 *   fm1_adc_read(ch)      0..1023, -1 on timeout
 */
#pragma once
#include <stdint.h>
#include "fm1_gpio.h"

#define FM1_ADC_CON (*(volatile uint32_t *)0x13100u)
#define FM1_ADC_RES (*(volatile uint32_t *)0x13104u)
#define FM1_WLA_CON0 (*(volatile uint32_t *)0x11900u)
enum { FM1_ADC_BATT = 3, FM1_ADC_MASTER = 4 };

/* Both are only ever analog inputs: PB1 held low for 8 s would reset the
 * chip (isd_config). */
static void fm1_adc_init(void)
{
    uint32_t m = (1u << 6) | (1u << 1);
    FM1_PR(FM1_PB, FM1_DIE) &= ~m;
    FM1_PR(FM1_PB, FM1_PU) &= ~m;
    FM1_PR(FM1_PB, FM1_PD) &= ~m;
    FM1_PR(FM1_PB, FM1_DIR) |= m;
}

static int32_t fm1_adc_read(uint32_t ch)
{
    uint32_t t, v;
    FM1_ADC_CON = 0;
    if (FM1_WLA_CON0 & (1u << 14))
        FM1_WLA_CON0 &= ~(1u << 14);
    FM1_ADC_CON = 0xF04Eu | ((ch & 0xFu) << 8);
    FM1_ADC_CON |= 0x10u;
    FM1_ADC_CON |= 0x40u;
    for (t = 0; t < 20000u; t++)
        if (FM1_ADC_CON & 0x80u)
            break;
    v = FM1_ADC_RES & 0x3FFu;
    FM1_ADC_CON = 0x40u;
    FM1_ADC_CON = 0;
    return t == 20000u ? -1 : (int32_t)v;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X pattern model: 32 patterns, each holding the 909, the 808, two 303s and the break.
 *
 * Plain data, no pointers, so a pattern copies with an assignment and the project
 * stores the bytes. The UI edits these in place from the main loop while the
 * sequencer reads them in the audio ISR: every field the sequencer reads is a
 * single byte or an aligned 32-bit word, so a read never sees half a write. A drum row is
 * two words (steps 1-32, 33-64): sm_get / sm_flip below. */
#pragma once
#include <stdint.h>

#define NPAT 32
#define NSTEPS 64
#define NSW (NSTEPS / 32)            /* 32-bit words in a row of steps */
#define NDRUM 11                     /* tracks per drum machine: the 11 black keys */
#define NKIT 2                       /* 0 = 909 (drum909.h order), 1 = 808 (drum808.h order) */
#define NBASS 2                      /* 303 A, 303 B */

enum { RATE_16, RATE_16T, RATE_32, RATE_8T, NRATES };      /* step length */
enum { DIR_FWD, DIR_REV, DIR_PINGPONG, DIR_RANDOM, NDIRS };  /* 303 playback direction */
enum { G_REST, G_NOTE, G_TIE };                             /* 303 step gate */

/* 303 step: velocity 1..127; zero means the legacy/default velocity (100). */
/* 0 = legacy gate; 1..15 = captured release fraction of this playback slot. */
#define BS_END_SHIFT 4u
#define BS_GATE_MASK 0x03u
#define BS_ACCENT 0x04u
#define BS_SLIDE 0x08u                /* slide INTO the next step (303 semantics) */
typedef struct {
    uint8_t note;                     /* MIDI note */
    uint8_t flags;                    /* gate | BS_ACCENT | BS_SLIDE | endpoint << 4 */
    uint8_t velocity;
} bstep_t;
#define BASS_VELOCITY_DEFAULT 100u
static inline uint8_t bstep_velocity(const bstep_t *s)
{
    return s->velocity ? (s->velocity > 127u ? 127u : s->velocity) : BASS_VELOCITY_DEFAULT;
}

/* TB-3PO settings of one 303 line: the line is reproducible from these and the seed */
typedef struct {
    uint8_t density, accent, slide;   /* probabilities 0..100 % */
    uint8_t oct_range;                /* 1..3 */
    uint8_t root;                     /* 0 = C .. 11 = B */
    uint8_t scale;                    /* tb3po.h SCALES */
    uint8_t base_oct;                 /* octave of the root: note = 12 * (base_oct + 1) + root */
    uint8_t mutate_bars;              /* auto-mutate every N bars, 0 = off */
    uint32_t seed;
} tb3po_cfg_t;

typedef struct {
    bstep_t step[NSTEPS];
    uint8_t len;                      /* 1..64 */
    uint8_t rate;                     /* RATE_* */
    uint8_t dir;                      /* DIR_* */
    uint8_t transpose;                /* semitones + 24 (24 = none), applied when played */
    tb3po_cfg_t gen;
} bpart_t;

typedef struct {
    uint32_t hit[NDRUM][NSW];         /* step s (sm_get): the instrument plays */
    uint32_t accent[NSW];             /* the total-accent row */
    uint8_t len;                      /* 1..64 */
    uint8_t rate;
    uint8_t rsv[2];
} dpart_t;

/* BREAK: the generator's settings (dsp/breaks.h) and the steps it may play on */
enum { BRK_COMPLEX, BRK_ANCHOR, BRK_ROLL, BRK_FILL, BRK_R2, BRK_R3, BRK_R4, BRK_R8,
       BRK_PHRASE, BRK_BCHANCE, BRK_ALEN, BRK_BLEN, BRK_NSET };
typedef struct {
    uint32_t steps;                   /* bit s = the break may sound on 16th s of the bar */
    uint8_t set[BRK_NSET];            /* breaks.h param values, in BRK_* order */
    uint8_t slot_a, slot_b;           /* loop A / B: the built-in bank, then the user slots (engine_brk_slot_names) */
    uint8_t slice_mode;               /* 0 = MIDI notes 36-43; 1 = every note, slice = note mod 8 */
    uint8_t rsv;
    uint8_t slice[16];                /* per 16th: 0 = the generator chooses, 1..8 = loop A's slice 1..8 */
} brkpart_t;

typedef struct {
    dpart_t drum[NKIT];
    bpart_t bass[NBASS];
    brkpart_t brk;
    uint8_t swing;                    /* 0..100: 0 = straight (50 %), 100 = 75 % shuffle */
    uint8_t rsv[3];
} pattern_t;

static inline int bstep_gate(const bstep_t *s) { return s->flags & BS_GATE_MASK; }

/* a row of steps (NSW words): step s */
static inline int sm_get(const uint32_t *m, int s) { return (int)((m[s >> 5] >> (s & 31)) & 1u); }
static inline void sm_flip(uint32_t *m, int s) { m[s >> 5] ^= 1u << (s & 31); }
static inline void sm_set(uint32_t *m, int s) { m[s >> 5] |= 1u << (s & 31); }
static inline int sm_any(const uint32_t *m)
{
    uint32_t a = 0;
    int k;
    for (k = 0; k < NSW; k++)
        a |= m[k];
    return a != 0;
}

/* default empty pattern: 16 steps, straight, 303 lines empty with TB-3PO defaults */
void pattern_init(pattern_t *p, uint32_t seed_a, uint32_t seed_b);

/* SPDX-License-Identifier: GPL-3.0-only */
#ifndef X0X_UI_WAVEFORM_H
#define X0X_UI_WAVEFORM_H
#include "../dsp/fastmath.h"
#include "../../../experiments/wobble/blep.h"
/* Raw periodic SHAPE cue, not an oscilloscope or the modulated/filtered output.
 * One normalized cycle, fixed reference phase increment. These renderer-only
 * equations mirror wobble.c; host proof compares the actual private evaluator.
 * No audio state, note frequency, gain, envelope or phase is read or changed. */
#define UI_WAVE_REFERENCE_STEP (1.0f / 128.0f)
static float ui_miami_wave_value(int pulse, int selected, float phase)
{
    phase -= fm_floorf(phase);
    if (!selected) return 4.0f * fm_fabsf(phase - 0.5f) - 1.0f;
    if (pulse) {
        const float duty=0.10f, low=-duty/(1.0f-duty);
        float shifted=phase-duty; shifted-=fm_floorf(shifted);
        float v=phase<duty?1.0f:low;
        v+=wobble_blep(phase,UI_WAVE_REFERENCE_STEP);
        v-=(1.0f-low)*wobble_blep(shifted,UI_WAVE_REFERENCE_STEP);
        return v;
    }
    {
        float th=2.0f*FM_PI*phase;
        return 1.0000000000f*fm_sinf(th)
            +0.3521721782f*fm_sinf(3.0f*th)
            +0.2104254119f*fm_sinf(5.0f*th)
            +0.1394680557f*fm_sinf(7.0f*th)
            +0.0914483780f*fm_sinf(9.0f*th)
            +0.0539063596f*fm_sinf(11.0f*th)
            +0.0225654210f*fm_sinf(13.0f*th)
            +0.0042509901f*fm_sinf(15.0f*th);
    }
}
#endif

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Publish a nightly installer only after Elite and Pro development validation.

publish_valid_nightly() is the function the Validate stage calls when a nightly
is valid. It checks both development records again and writes eligible build
records. With push=True it also records a non-force handoff commit on the
named branch of the given remote. That handoff is not a deploy of
gobbajogger/x0x37-for-Loopy-Pro_nightly gh-pages and does not run that
repository's publisher. Do not report PUBLISHED LIVE. A failed or invalid
build is not written and not pushed. Production gh-pages is not a destination.

Call site to wire after #134 merges
------------------------------------
Do not put this call inside tools/stage_handoff.py. That module only records
the stage thread. handoff(), record_thread(), and advance() also move Audit,
Implement, Test, and Publish, and advance() enters Validate at the start of
the stage.

On cursor/stage-handoff-fbdd at 11caf84, the Validate stage ends by calling
handoff() (tools/stage_handoff.py line 168) with the next stage:

    handoff(ledger, "Merge", thread_id, timestamp)

Wire the record immediately before that call. It does not publish the live
installer. Skip the stage handoff when it raises:

    from publish_nightly import publish_valid_nightly
    publish_valid_nightly(
        repo, elite_record, pro_record, elite_fwsc, pro_fwsc, out)
    handoff(ledger, "Merge", thread_id, timestamp)
"""
import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import dev_validate  # noqa: E402
import make_pages  # noqa: E402
import release_alloc  # noqa: E402
from firmware_build_labels import canonical_version, release_display, version_of_product  # noqa: E402
from make_site import product_of  # noqa: E402

LABEL = "DEV / HARDWARE TEST — DEVICE NOT TESTED"
BANNER = (
    "DEV / HARDWARE TEST — DEVICE NOT TESTED. "
    "Only an Elite and Pro development build that passed validation is listed. "
    "A failed or invalid build is not published."
)
NIGHTLY_PAGES = "https://gobbajogger.github.io/x0x37-for-Loopy-Pro_nightly/"
LIVE_REPOSITORY = "gobbajogger/x0x37-for-Loopy-Pro_nightly"
LIVE_REF = "gh-pages"
BRANCH = "nightly-pages"
# gh-pages is production. main/master and the firmware nightly branch are source.
FORBIDDEN = {"gh-pages", "main", "master", "nightly"}
PRODUCTS = {"pro": "SMK-37 Pro_900", "elite": "SMK-37 Elite_900"}


def _embedded_version(product, model):
    """None for a legacy model_900 package. Refuse any other non-codec identity."""
    if model not in PRODUCTS:
        raise NightlyPublishError("nightly model must be elite or pro")
    if product == PRODUCTS[model]:
        return None
    try:
        found = version_of_product(product, model)
    except (ValueError, TypeError, AttributeError) as exc:
        raise NightlyPublishError(f"{model} package identity {product!r} is not a validated version") from exc
    if found is None:
        raise NightlyPublishError(f"{model} package identity {product!r} is not a validated version")
    return found
HEX40 = re.compile(r"^[0-9a-f]{40}$")
HEX64 = re.compile(r"^[0-9a-f]{64}$")
FWSC_NAME = re.compile(r"^[A-Za-z0-9._-]+\.fwsc$")


class NightlyPublishError(ValueError):
    """The nightly is not valid, so the installer page was not published."""


def _commit_of(record):
    commit = record.get("commit")
    if not isinstance(commit, str) or not HEX40.fullmatch(commit):
        raise NightlyPublishError("validation record has no full commit")
    return commit


def _verify_records(repo, elite_record, pro_record, elite_fwsc, pro_fwsc, elite_ctl, pro_ctl, ledger=None):
    verified = []
    for model, record_path, fwsc, ctl in (
        ("elite", elite_record, elite_fwsc, elite_ctl),
        ("pro", pro_record, pro_fwsc, pro_ctl),
    ):
        record_path, fwsc = Path(record_path), Path(fwsc)
        if not record_path.is_file() or not fwsc.is_file():
            raise NightlyPublishError(f"{model} validation record or package is missing")
        try:
            preview = json.loads(record_path.read_text(encoding="utf-8"))
        except (OSError, ValueError) as error:
            raise NightlyPublishError(f"{model} validation record is unreadable") from error
        if preview.get("model") != model or preview.get("result") != "DEV CHECKED" or preview.get("config") != "dev":
            raise NightlyPublishError(f"{model} record is not a passing development validation")
        commit = _commit_of(preview)
        try:
            record = dev_validate.verify(repo, commit, record_path, fwsc, ctl)
        except (OSError, ValueError, KeyError, subprocess.SubprocessError) as error:
            raise NightlyPublishError(f"{model} did not pass validation: {error}") from error
        if record.get("model") != model or record.get("commit") != commit:
            raise NightlyPublishError(f"{model} record does not match the validated commit")
        raw = fwsc.read_bytes()
        if b"FELUCCA-LOADER-1" not in raw:
            raise NightlyPublishError(f"{model} package has no update loader")
        try:
            product = product_of(raw)
        except (ValueError, OSError) as error:
            raise NightlyPublishError(f"{model} package identity is unreadable") from error
        embedded = _embedded_version(product, model)
        recorded = record.get("firmware_version")
        if embedded is None:
            if recorded is not None:
                raise NightlyPublishError(f"{model} legacy package has no numeric version")
        else:
            try:
                recorded = canonical_version(recorded)
            except (ValueError, TypeError) as error:
                raise NightlyPublishError(f"{model} validation record has no canonical firmware version") from error
            if recorded != embedded:
                raise NightlyPublishError(f"{model} package version does not match its validation record")
            firmware = record.get("firmware")
            digest = make_pages.sha256_file(fwsc)
            if not isinstance(firmware, dict) or firmware.get("product") != product or firmware.get("package_sha256") != digest:
                raise NightlyPublishError(f"{model} record does not match the package bytes")
            if firmware.get("firmware_version") != embedded:
                raise NightlyPublishError(f"{model} record identity does not match the package")
            controller_sha = make_pages.sha256_file(Path(ctl)) if ctl else None
            try:
                receipt = release_alloc.require_receipt(
                    repo, embedded, commit, model, digest, controller_sha, ledger)
            except release_alloc.ReleaseError as exc:
                raise NightlyPublishError(str(exc)) from exc
            record["_bound_controller_sha256"] = receipt["controller_sha256"]
        record = dict(record)
        record["_embedded_version"] = embedded
        record["_product"] = product
        verified.append((model, record, fwsc, Path(ctl) if ctl else None))
    elite, pro = verified
    if elite[1]["commit"] != pro[1]["commit"] or elite[1].get("tree") != pro[1].get("tree"):
        raise NightlyPublishError("Elite and Pro are not the same validated source")
    if elite[1].get("_embedded_version") != pro[1].get("_embedded_version"):
        raise NightlyPublishError("Elite and Pro firmware versions differ")
    return elite[1]["commit"], verified


def _pkg_name(pkg):
    if not isinstance(pkg, str) or "\\" in pkg or pkg.startswith("http"):
        return None
    name = Path(pkg).name
    if not FWSC_NAME.fullmatch(name):
        return None
    return name


def _model_entry_ok(key, model):
    if key not in PRODUCTS or not isinstance(model, dict):
        return False
    product = model.get("product")
    if not isinstance(product, str):
        return False
    if product == PRODUCTS[key]:
        pass
    else:
        try:
            if version_of_product(product, key) is None:
                return False
        except (ValueError, TypeError, AttributeError):
            return False
    if model.get("fromRelease") or model.get("qualified") is False or model.get("installable") is False:
        return False
    if model.get("revoked") or model.get("blocked") or model.get("withdrawn"):
        return False
    if model.get("hardware_tested") not in (None, False) or model.get("status") not in (None, "dev-checked"):
        return False
    sha = model.get("sha256")
    size = model.get("size")
    if not isinstance(sha, str) or not HEX64.fullmatch(sha):
        return False
    if not isinstance(size, int) or isinstance(size, bool) or size < 960:
        return False
    return _pkg_name(model.get("pkg")) is not None


def _version_ok(entry):
    if not isinstance(entry, dict):
        return False
    if entry.get("status") != "dev-checked" or entry.get("config") != "dev":
        return False
    if entry.get("hardware_tested") is not False or entry.get("label") != LABEL:
        return False
    if entry.get("qualified") is False or entry.get("installable") is False:
        return False
    if entry.get("revoked") or entry.get("blocked") or entry.get("withdrawn"):
        return False
    if not isinstance(entry.get("version"), str) or not entry["version"]:
        return False
    if not HEX40.fullmatch(str(entry.get("source_commit", ""))):
        return False
    models = entry.get("models")
    if not isinstance(models, dict) or not models:
        return False
    if any(key not in PRODUCTS for key in models):
        return False
    if not all(_model_entry_ok(key, model) for key, model in models.items()):
        return False
    decoded = []
    for key, model in models.items():
        product = model.get("product")
        if product == PRODUCTS[key]:
            decoded.append(None)
            continue
        if not isinstance(product, str):
            return False
        try:
            decoded.append(version_of_product(product, key))
        except (ValueError, TypeError, AttributeError):
            return False
    if any(item is None for item in decoded) and any(item is not None for item in decoded):
        return False
    if decoded[0] is None:
        return entry.get("firmware_version") in (None,) and entry.get("release_display") in (None,)
    if len(set(decoded)) != 1 or entry.get("firmware_version") != decoded[0]:
        return False
    if entry.get("version") != decoded[0] or entry.get("release_display") != release_display(decoded[0]):
        return False
    return True


def _same_numeric_release(old, new):
    """Exact republish of one allocated release. Any other same-version record collides."""
    if not new.get("firmware_version"):
        return False
    if (old.get("firmware_version") != new.get("firmware_version")
            or old.get("source_commit") != new.get("source_commit")
            or old.get("source_tree") != new.get("source_tree")
            or old.get("release_display") != new.get("release_display")):
        return False
    old_models = old.get("models") if isinstance(old.get("models"), dict) else {}
    new_models = new.get("models") if isinstance(new.get("models"), dict) else {}
    if set(old_models) != set(new_models):
        return False
    for key, model in new_models.items():
        prev = old_models.get(key)
        if not isinstance(prev, dict):
            return False
        for field in ("product", "sha256", "controller_sha256"):
            if prev.get(field) != model.get(field):
                return False
    return True


def _kept_versions(catalog, merge_from, version, incoming):
    """Prior nightlies stay only when their bytes still match the recorded hash."""
    kept = []
    firmware = (Path(merge_from) / "firmware") if merge_from else None
    for entry in catalog.get("versions", []):
        if entry.get("version") == version:
            if incoming.get("firmware_version") and not _same_numeric_release(entry, incoming):
                raise NightlyPublishError(
                    "catalog version " + str(version) + " already records a different source or package")
            continue
        if not _version_ok(entry):
            continue
        if firmware is None:
            continue
        fresh = dict(entry)
        fresh["models"] = {}
        good = True
        for key, model in entry["models"].items():
            name = _pkg_name(model["pkg"])
            path = firmware / name
            if not path.is_file() or make_pages.sha256_file(path) != model["sha256"]:
                good = False
                break
            copied = dict(model)
            copied["pkg"] = f"../firmware/{name}"
            fresh["models"][key] = copied
        if good:
            kept.append(fresh)
    return kept


def _new_version(commit, verified):
    embedded = verified[0][1].get("_embedded_version")
    # The catalog version is the machine identity. A filename is not an identity.
    # Legacy packages keep the historical nightly label and stay unversioned.
    version = embedded if embedded else "nightly-" + commit[:12]
    display = release_display(embedded) if embedded else None
    models = {}
    copies = {}
    for model, record, fwsc, ctl in verified:
        name = f"x0x37-{version}-elite.fwsc" if model == "elite" else f"x0x37-{version}.fwsc"
        raw_size = fwsc.stat().st_size
        entry = {
            "product": record.get("_product") or PRODUCTS[model],
            "pkg": f"../firmware/{name}",
            "sha256": make_pages.sha256_file(fwsc),
            "size": raw_size,
            "status": "dev-checked",
            "hardware_tested": False,
        }
        if record.get("_bound_controller_sha256"):
            entry["controller_sha256"] = record["_bound_controller_sha256"]
        elif ctl:
            entry["controller_sha256"] = make_pages.sha256_file(ctl)
        if record.get("artifacts", {}).get("package", {}).get("sha256") != entry["sha256"]:
            raise NightlyPublishError(f"{model} package hash is not the validated artifact")
        models[model] = entry
        copies[name] = fwsc
    entry = {
        "version": version,
        "label": LABEL,
        "status": "dev-checked",
        "config": "dev",
        "hardware_tested": False,
        "qualified": True,
        "installable": True,
        "source_commit": commit,
        "source_tree": verified[0][1].get("tree"),
        "models": models,
    }
    if embedded:
        entry["firmware_version"] = embedded
        entry["release_display"] = display
    return version, entry, copies


def _catalog(commit, verified, merges):
    version, entry, copies = _new_version(commit, verified)
    versions = []
    seen = set()
    for merge in merges:
        if not merge:
            continue
        previous = make_pages.load_catalog(Path(merge) / "versions.json")
        for item in _kept_versions(previous, merge, version, entry):
            if item["version"] in seen:
                continue
            seen.add(item["version"])
            versions.append(item)
    versions.append(entry)
    versions.sort(key=lambda item: str(item["version"]), reverse=True)
    catalog = {
        "repo": make_pages.REPO,
        "pages": NIGHTLY_PAGES,
        "channel": "nightly",
        "importsReleases": False,
        "latest": version,
        "versions": versions,
    }
    return version, catalog, copies


def _destination(branch):
    """Fold a fully qualified ref to its short name, then apply the denylist.

    `refs/heads/main` is the same destination as `main`. The check uses the short
    name, and the push uses that name too, so a qualified form cannot slip past.
    """
    if not isinstance(branch, str):
        raise NightlyPublishError("refusing to publish a nightly onto " + repr(branch))
    name = branch.strip()
    if name.startswith("+"):
        name = name[1:]
    while name.startswith("refs/heads/"):
        name = name[len("refs/heads/"):]
    parts = name.split("/")
    if (not name or name.lower() in FORBIDDEN or name.startswith("-")
            or any(part in {"", ".", ".."} for part in parts)
            or not re.fullmatch(r"[A-Za-z0-9._/-]{1,80}", name)):
        raise NightlyPublishError(f"refusing to publish a nightly onto {branch}")
    return name


def _remote_tip(remote, branch):
    """SHA currently stored on the handoff branch, or None when the branch is absent."""
    listed = subprocess.run(
        ["git", "ls-remote", remote, f"refs/heads/{branch}"],
        capture_output=True, text=True, check=True)
    line = listed.stdout.strip().splitlines()
    if not line or not line[0].strip():
        return None
    return line[0].split()[0]


def _materialize(remote, branch, dest):
    """Copy the handoff branch's tree. The caller keeps prior candidates from it."""
    scratch = Path(tempfile.mkdtemp(prefix=".nightly-fetch-"))
    try:
        subprocess.run(["git", "init", "-q"], cwd=scratch, check=True)
        subprocess.run(["git", "remote", "add", "origin", remote], cwd=scratch, check=True)
        subprocess.run(["git", "fetch", "-q", "origin", branch], cwd=scratch, check=True)
        subprocess.run(["git", "checkout", "-q", "FETCH_HEAD"], cwd=scratch, check=True)
        dest.mkdir(parents=True, exist_ok=True)
        for item in scratch.iterdir():
            if item.name == ".git":
                continue
            target = dest / item.name
            if item.is_dir():
                shutil.copytree(item, target)
            else:
                shutil.copy2(item, target)
    finally:
        shutil.rmtree(scratch, ignore_errors=True)


def _prior_tree(dirs):
    present = [Path(path) for path in dirs if path]
    if not present:
        return None
    if len(present) == 1:
        return present[0]
    combined = Path(tempfile.mkdtemp(prefix=".nightly-prior-"))
    firmware = combined / "firmware"
    firmware.mkdir()
    for directory in present:
        source = directory / "firmware"
        if not source.is_dir():
            continue
        for package in source.glob("*.fwsc"):
            target = firmware / package.name
            if not target.exists():
                shutil.copy2(package, target)
    return combined


def _overlay(work, site):
    for child in list(work.iterdir()):
        if child.name == ".git":
            continue
        if child.is_dir():
            shutil.rmtree(child)
        else:
            child.unlink()
    for item in Path(site).iterdir():
        target = work / item.name
        if item.is_dir():
            shutil.copytree(item, target)
        else:
            shutil.copy2(item, target)


def _push(site, remote, branch, expected):
    """Commit the site as a child of expected and fast-forward the handoff branch.

    A new root is only the first commit. Later handoffs fetch the remote tip and
    use it as the parent, so a non-force push can move the branch. This does not
    deploy the nightly website repository.
    """
    branch = _destination(branch)
    if not remote:
        raise NightlyPublishError("nightly remote is not set; production pages are not a nightly destination")
    work = Path(tempfile.mkdtemp(prefix=".nightly-commit-"))
    try:
        tip = _remote_tip(remote, branch)
        if tip != expected:
            raise NightlyPublishError("remote handoff moved; the descendant was not pushed")
        subprocess.run(["git", "init", "-q"], cwd=work, check=True)
        subprocess.run(["git", "remote", "add", "origin", remote], cwd=work, check=True)
        if tip:
            subprocess.run(["git", "fetch", "-q", "origin", branch], cwd=work, check=True)
            fetched = subprocess.check_output(
                ["git", "rev-parse", "FETCH_HEAD"], cwd=work, text=True).strip()
            if fetched != tip:
                raise NightlyPublishError("remote handoff moved; the descendant was not pushed")
            subprocess.run(["git", "checkout", "-q", "-B", branch, "FETCH_HEAD"], cwd=work, check=True)
        else:
            subprocess.run(["git", "checkout", "-q", "--orphan", branch], cwd=work, check=True)
        _overlay(work, site)
        subprocess.run(["git", "add", "-A"], cwd=work, check=True)
        message = f"Nightly handoff {branch}"
        subprocess.run(
            ["git", "-c", "user.name=Nightly publish", "-c", "user.email=nightly@localhost",
             "commit", "-q", "--allow-empty", "-m", message],
            cwd=work, check=True)
        if tip:
            parent = subprocess.check_output(["git", "rev-parse", "HEAD^"], cwd=work, text=True).strip()
            if parent != tip:
                raise NightlyPublishError("handoff is not a descendant of the remote tip")
        head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=work, text=True).strip()
        # No --force. A non-fast-forward update is rejected and the remote SHA stays.
        subprocess.run(["git", "push", "-q", "origin", f"HEAD:{branch}"], cwd=work, check=True)
        published = _remote_tip(remote, branch)
        if published != head:
            raise NightlyPublishError("remote handoff SHA is not the descendant commit")
        return head
    finally:
        shutil.rmtree(work, ignore_errors=True)


def _handoff_record():
    """State that this directory is not the live nightly website."""
    return {
        "schema": 1,
        "result": "HANDOFF",
        "live_deploy": False,
        "pages_repository": LIVE_REPOSITORY,
        "pages_ref": LIVE_REF,
        "note": (
            "Not a deploy of gobbajogger/x0x37-for-Loopy-Pro_nightly gh-pages. "
            "This does not run that repository's publisher."
        ),
    }


def publish_valid_nightly(repo, elite_record, pro_record, elite_fwsc, pro_fwsc, out,
                          elite_ctl=None, pro_ctl=None, remote=None, push=False,
                          branch=BRANCH, merge=None, ledger=None):
    """Record a validated nightly page. A push is a handoff, not a live deploy.

    Returns the page directory. Raises NightlyPublishError without writing `out`
    and without pushing when either build is missing, failed, or not the matching
    development package. `push` fast-forwards `branch` on `remote` to a descendant
    commit and keeps candidates already stored on that branch.
    """
    branch_name = _destination(branch) if push else None
    if push:
        remote = remote or os.environ.get("X0X_NIGHTLY_REMOTE")
        if not remote:
            raise NightlyPublishError("nightly remote is not set; production pages are not a nightly destination")
    expected = None
    remote_site = None
    if push:
        expected = _remote_tip(remote, branch_name)
        if expected:
            remote_site = Path(tempfile.mkdtemp(prefix=".nightly-remote-"))
            _materialize(remote, branch_name, remote_site)
    merges = [Path(merge)] if merge else []
    if remote_site:
        merges.append(remote_site)
    prior = None
    try:
        commit, verified = _verify_records(
            repo, elite_record, pro_record, elite_fwsc, pro_fwsc, elite_ctl, pro_ctl, ledger)
        version, catalog, copies = _catalog(commit, verified, merges)
        prior = _prior_tree(merges)
        out = Path(out)
        if out.exists() and not out.is_dir():
            raise NightlyPublishError("nightly output exists and is not a directory")
        out.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(prefix=".nightly-", dir=str(out.parent)))
        backup = None
        recorded = False
        try:
            try:
                make_pages.write_site(staging, catalog, copies, prior, banner=BANNER)
                (staging / "handoff.json").write_text(
                    json.dumps(_handoff_record(), indent=2) + "\n", encoding="utf-8")
                if push:
                    _push(staging, remote, branch_name, expected)
                if out.exists():
                    backup = out.with_name(out.name + ".replaced")
                    if backup.exists():
                        shutil.rmtree(backup)
                    out.rename(backup)
                staging.rename(out)
                recorded = True
            except subprocess.CalledProcessError as error:
                raise NightlyPublishError("nightly handoff was not recorded") from error
        finally:
            if staging.exists():
                shutil.rmtree(staging, ignore_errors=True)
            if not recorded and backup and backup.exists() and not out.exists():
                backup.rename(out)
            if recorded and backup and backup.exists():
                shutil.rmtree(backup)
    finally:
        if remote_site:
            shutil.rmtree(remote_site, ignore_errors=True)
        if prior and prior not in merges:
            shutil.rmtree(prior, ignore_errors=True)
    print(f"nightly handoff {version} ({commit[:12]}) -> {out}")
    print(f"not a live deploy of {LIVE_REPOSITORY} {LIVE_REF}")
    if push:
        print(f"recorded non-force handoff on {branch_name}")
    return out


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--repo", default=".")
    parser.add_argument("--elite-record", required=True, type=Path)
    parser.add_argument("--elite-fwsc", required=True, type=Path)
    parser.add_argument("--elite-ctl", type=Path)
    parser.add_argument("--pro-record", required=True, type=Path)
    parser.add_argument("--pro-fwsc", required=True, type=Path)
    parser.add_argument("--pro-ctl", type=Path)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--merge", type=Path, help="previous nightly page whose valid packages to keep")
    parser.add_argument("--remote", help="git remote for the nightly installer page")
    parser.add_argument("--branch", default=BRANCH)
    parser.add_argument("--push", action="store_true")
    args = parser.parse_args(argv)
    try:
        publish_valid_nightly(
            args.repo, args.elite_record, args.pro_record, args.elite_fwsc, args.pro_fwsc, args.out,
            elite_ctl=args.elite_ctl, pro_ctl=args.pro_ctl, remote=args.remote, push=args.push,
            branch=args.branch, merge=args.merge)
    except NightlyPublishError as error:
        print("nightly not published: " + str(error), file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

